import re

RSOP = re.compile(r"^RSOP data for (?P<user>\S+) on (?P<computer>\S+) : (?P<mode>\S(?:.*?\S)?)\s*$")
CREATED = re.compile(r"^(?P<key>Created on) (?P<value>\S(?:.*?\S)?)\s*$")
BANNER = re.compile(r"^(?:Microsoft \(R\) Windows \(R\)|\S* ?Microsoft Corporation\. All rights reserved)")
RULE = re.compile(r"^\s*-{5,}\s*$")
SCOPE = re.compile(r"^(?P<scope>[A-Z][A-Z ]+ SETTINGS)\s*$")
KV = re.compile(r"^\s*(?P<key>[A-Za-z][^:]*?\??):\s+(?P<value>\S(?:.*?\S)?)\s*$")
DN = re.compile(r"^\s{4}(?P<dn>CN=\S(?:.*?\S)?)\s*$")
TITLE = re.compile(r"^\s{4}(?P<title>\S(?:.*?\S)?)\s*$")
ITEM = re.compile(r"^\s{8}(?P<name>\S(?:.*?\S)?)\s*$")
SUB = re.compile(r"^\s{12}(?P<key>[A-Za-z][^:]*?):\s+(?P<value>\S(?:.*?\S)?)\s*$")


def table_for(title):
    t = title.lower()
    if "group policy object" in t or "gpo" in t:
        return "gpos"
    if "security group" in t:
        return "security groups"
    return "items"


def parse(lines):
    rsop = {}
    scopes, items = [], {"gpos": [], "security groups": [], "items": []}
    used = {"rsop": [], "scopes": [], "gpos": [], "security groups": [], "items": []}
    cols = {"gpos": ["scope", "section", "name"], "security groups": ["scope", "section", "name"],
            "items": ["scope", "section", "name"]}
    skip = []
    scope, title, table, last = None, None, None, None
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if RULE.match(ln) or BANNER.match(ln):
            skip.append(j)
            continue
        m = SCOPE.match(ln)
        if m:
            scope = {"scope": m.group("scope"), "distinguished name": ""}
            scopes.append(scope)
            title = table = last = None
            used["scopes"].append(j)
            continue
        if scope is None:
            m = RSOP.match(ln) or CREATED.match(ln) or KV.match(ln)
            if m:
                d = m.groupdict()
                if "key" in d:
                    rsop[d["key"]] = d["value"]
                else:
                    rsop.update(d)
                used["rsop"].append(j)
            continue
        m = DN.match(ln)
        if m:
            scope["distinguished name"] = m.group("dn")
            used["scopes"].append(j)
            continue
        # a 4-space title right above a rule opens a list; its items are 8 spaces in
        m = TITLE.match(ln)
        if m and j + 1 < len(lines) and RULE.match(lines[j + 1]):
            title = m.group("title")
            table = table_for(title)
            last = None
            used[table].append(j)
            continue
        m = SUB.match(ln)
        if m and last is not None:
            last[m.group("key")] = m.group("value")
            if m.group("key") not in cols[table]:
                cols[table].append(m.group("key"))
            used[table].append(j)
            continue
        m = ITEM.match(ln)
        if m and table is not None:
            last = {"scope": scope["scope"], "section": title, "name": m.group("name")}
            items[table].append(last)
            used[table].append(j)
            continue
        m = KV.match(ln)
        if m:
            scope[m.group("key")] = m.group("value")
            used["scopes"].append(j)
    keys = ["scope", "distinguished name"]
    for s in scopes:
        keys += [k for k in s if k not in keys]
    blocks = [{"name": "rsop", "kind": "kv", "lines": used["rsop"], "records": [rsop]},
              {"name": "settings", "kind": "table", "lines": used["scopes"],
               "records": [{k: s.get(k, "") for k in keys} for s in scopes]}]
    for name in ("gpos", "security groups", "items"):
        blocks.append({"name": name, "kind": "table", "lines": used[name],
                       "records": [{k: r.get(k, "") for k in cols[name]} for r in items[name]]})
    return {"blocks": blocks, "skip": skip}
